#!/usr/bin/env bash
set -euo pipefail
source "$(dirname -- "${BASH_SOURCE[0]}")/../lib/common.sh"

N="${N:-21}"; W=$((N + 1)); ARCH="${ARCH:-native}"
LOW_LUT_K="${LOW_LUT_K:-$((W / 2))}"; HIGH_LUT_K="${HIGH_LUT_K:-$((W - LOW_LUT_K - 1))}"
TRANSPOSE_MODE="${TRANSPOSE_MODE:-pipeline}"
DEPTHCODE_DECODE_LOAD="${DEPTHCODE_DECODE_LOAD:-ldg}"; RANKSTREAM_LUT_LOAD="${RANKSTREAM_LUT_LOAD:-ldg}"
RANKFORMULA_NOMETA_BLOCK="${RANKFORMULA_NOMETA_BLOCK:-4}"
RANKFORMULA_NOMETA_WARPSHARE="${RANKFORMULA_NOMETA_WARPSHARE:-0}"
RANKFORMULA_NOMETA_COOPGROUP="${RANKFORMULA_NOMETA_COOPGROUP:-0}"
RANKFORMULA_NOMETA_COOP_UNROLL="${RANKFORMULA_NOMETA_COOP_UNROLL:-1}"
RANKFORMULA_NOMETA_GROUP56="${RANKFORMULA_NOMETA_GROUP56:-0}"
RANKFORMULA_NOMETA_GROUP61="${RANKFORMULA_NOMETA_GROUP61:-0}"
RANKFORMULA_NOMETA_DIRECTMAP="${RANKFORMULA_NOMETA_DIRECTMAP:-0}"
RANKFORMULA_DIRECTGATHER="${RANKFORMULA_DIRECTGATHER:-0}"
RANKFORMULA_DIRECTGATHER_FORCE7="${RANKFORMULA_DIRECTGATHER_FORCE7:-0}"
RANKFORMULA_MLP_WINDOW4="${RANKFORMULA_MLP_WINDOW4:-0}"
RANKFORMULA_ABSTRACT_SELECT8="${RANKFORMULA_ABSTRACT_SELECT8:-0}"
RANKFORMULA_ABSTRACT_DEPTH4="${RANKFORMULA_ABSTRACT_DEPTH4:-0}"
RANKFORMULA_ABSTRACT_SRCPACK10="${RANKFORMULA_ABSTRACT_SRCPACK10:-0}"
RANKFORMULA_GATHER_MLP="${RANKFORMULA_GATHER_MLP:-1}"
MAXRREGCOUNT="${MAXRREGCOUNT:-0}"
PM_ACCUM="${PM_ACCUM:-0}"; TERNARY_KEY4="${TERNARY_KEY4:-1}"; PTXAS_VERBOSE="${PTXAS_VERBOSE:-0}"
if (( LOW_LUT_K <= 0 || HIGH_LUT_K <= 0 || LOW_LUT_K + HIGH_LUT_K + 1 != W || LOW_LUT_K > 14 || HIGH_LUT_K > 14 )); then exit 2; fi
case "$RANKFORMULA_NOMETA_BLOCK" in 4|8|16) ;; *) echo "RANKFORMULA_NOMETA_BLOCK must be 4, 8, or 16" >&2; exit 2;; esac
[[ "$MAXRREGCOUNT" =~ ^[0-9]+$ ]] || { echo "MAXRREGCOUNT must be a non-negative integer" >&2; exit 2; }
if (( MAXRREGCOUNT != 0 && (MAXRREGCOUNT < 32 || MAXRREGCOUNT > 255) )); then echo "MAXRREGCOUNT must be 0 or 32..255" >&2; exit 2; fi
for x in RANKFORMULA_NOMETA_WARPSHARE RANKFORMULA_NOMETA_COOPGROUP RANKFORMULA_NOMETA_COOP_UNROLL RANKFORMULA_NOMETA_GROUP56 RANKFORMULA_NOMETA_GROUP61 RANKFORMULA_NOMETA_DIRECTMAP RANKFORMULA_DIRECTGATHER RANKFORMULA_DIRECTGATHER_FORCE7 RANKFORMULA_MLP_WINDOW4 RANKFORMULA_ABSTRACT_SELECT8 RANKFORMULA_ABSTRACT_DEPTH4 RANKFORMULA_ABSTRACT_SRCPACK10 RANKFORMULA_GATHER_MLP PM_ACCUM TERNARY_KEY4 PTXAS_VERBOSE; do v="${!x}"; [[ "$v" == 0 || "$v" == 1 ]] || { echo "$x must be 0 or 1" >&2; exit 2; }; done
if [[ "$RANKFORMULA_NOMETA_COOPGROUP" == 1 && "$RANKFORMULA_NOMETA_WARPSHARE" != 1 ]]; then echo "COOPGROUP requires WARPSHARE=1" >&2; exit 2; fi
if [[ "$RANKFORMULA_NOMETA_GROUP56" == 1 && "$RANKFORMULA_NOMETA_COOPGROUP" != 1 ]]; then echo "GROUP56 requires COOPGROUP=1" >&2; exit 2; fi
if [[ "$RANKFORMULA_NOMETA_GROUP61" == 1 && "$RANKFORMULA_NOMETA_COOPGROUP" != 1 ]]; then echo "GROUP61 requires COOPGROUP=1" >&2; exit 2; fi
if [[ "$RANKFORMULA_NOMETA_GROUP56" == 1 && "$RANKFORMULA_NOMETA_GROUP61" == 1 ]]; then echo "GROUP56 and GROUP61 are mutually exclusive" >&2; exit 2; fi
if [[ "$RANKFORMULA_NOMETA_DIRECTMAP" == 1 && "$RANKFORMULA_NOMETA_GROUP61" != 1 ]]; then echo "DIRECTMAP requires GROUP61=1" >&2; exit 2; fi
if [[ "$RANKFORMULA_DIRECTGATHER" == 1 && "$RANKFORMULA_NOMETA_DIRECTMAP" != 1 ]]; then echo "DIRECTGATHER requires DIRECTMAP=1" >&2; exit 2; fi
if [[ "$RANKFORMULA_DIRECTGATHER" == 1 && "$RANKFORMULA_GATHER_MLP" != 1 ]]; then echo "DIRECTGATHER requires GATHER_MLP=1" >&2; exit 2; fi
if [[ "$RANKFORMULA_DIRECTGATHER_FORCE7" == 1 && "$RANKFORMULA_DIRECTGATHER" != 1 ]]; then echo "DIRECTGATHER_FORCE7 requires DIRECTGATHER=1" >&2; exit 2; fi
if [[ "$RANKFORMULA_MLP_WINDOW4" == 1 && "$RANKFORMULA_DIRECTGATHER" != 1 ]]; then echo "MLP_WINDOW4 currently requires DIRECTGATHER=1" >&2; exit 2; fi
if [[ "$RANKFORMULA_DIRECTGATHER_FORCE7" == 1 && "$RANKFORMULA_MLP_WINDOW4" == 1 ]]; then echo "FORCE7 and MLP_WINDOW4 are isolated A/B modes" >&2; exit 2; fi
if [[ "$RANKFORMULA_DIRECTGATHER" == 1 && ( "$RANKFORMULA_ABSTRACT_SELECT8" != 1 || "$RANKFORMULA_ABSTRACT_SRCPACK10" != 1 ) ]]; then echo "DIRECTGATHER requires SELECT8=1 and SRCPACK10=1" >&2; exit 2; fi
if [[ "$RANKFORMULA_ABSTRACT_DEPTH4" == 1 && "$RANKFORMULA_ABSTRACT_SELECT8" != 1 ]]; then echo "DEPTH4 requires SELECT8=1" >&2; exit 2; fi
if [[ "$RANKFORMULA_ABSTRACT_SRCPACK10" == 1 && "$RANKFORMULA_ABSTRACT_SELECT8" != 1 ]]; then echo "SRCPACK10 requires SELECT8=1" >&2; exit 2; fi
case "$TRANSPOSE_MODE" in
  sync) SRC_NAME="oneesan_cuda_gridfp_b300_bucket_snake_onepass_pattern10_depthcode_warpstriped_delta_direct_affine_rankformula_nometa4_abstract_graph_batch.cu" ;;
  events) SRC_NAME="oneesan_cuda_gridfp_b300_bucket_snake_onepass_pattern10_depthcode_warpstriped_delta_direct_affine_rankformula_nometa4_abstract_graph_batch_events.cu" ;;
  pipeline) SRC_NAME="oneesan_cuda_gridfp_b300_bucket_snake_onepass_pattern10_depthcode_warpstriped_delta_direct_affine_rankformula_nometa4_abstract_graph_batch_pipeline.cu" ;;
  *) exit 2 ;;
esac
case "$DEPTHCODE_DECODE_LOAD" in global) P10DC_DECODE_LDG=0 ;; ldg) P10DC_DECODE_LDG=1 ;; *) exit 2;; esac
P10DC_RANKSTREAM_LUT_LDG=0; P10DC_RANKSTREAM_LUT_PAD256=0
case "$RANKSTREAM_LUT_LOAD" in constant) ;; ldg) P10DC_RANKSTREAM_LUT_LDG=1 ;; ldg256) P10DC_RANKSTREAM_LUT_LDG=1; P10DC_RANKSTREAM_LUT_PAD256=1 ;; *) exit 2;; esac
SRC="$(repo_path "src/cuda/b300/$SRC_NAME")"
mode_suffix=""; [[ "$RANKFORMULA_NOMETA_WARPSHARE" == 1 ]] && mode_suffix="_warpshare"; [[ "$RANKFORMULA_NOMETA_COOPGROUP" == 1 ]] && mode_suffix="_coopgroup_u${RANKFORMULA_NOMETA_COOP_UNROLL}"; [[ "$RANKFORMULA_NOMETA_GROUP56" == 1 ]] && mode_suffix="${mode_suffix}_group56"; [[ "$RANKFORMULA_NOMETA_GROUP61" == 1 ]] && mode_suffix="${mode_suffix}_group61"; [[ "$RANKFORMULA_NOMETA_DIRECTMAP" == 1 ]] && mode_suffix="${mode_suffix}_directmap"; [[ "$RANKFORMULA_DIRECTGATHER" == 1 ]] && mode_suffix="${mode_suffix}_directgather"; [[ "$RANKFORMULA_DIRECTGATHER_FORCE7" == 1 ]] && mode_suffix="${mode_suffix}_force7"; [[ "$RANKFORMULA_MLP_WINDOW4" == 1 ]] && mode_suffix="${mode_suffix}_window4"; [[ "$RANKFORMULA_ABSTRACT_SELECT8" == 1 ]] && mode_suffix="${mode_suffix}_select8"; [[ "$RANKFORMULA_ABSTRACT_DEPTH4" == 1 ]] && mode_suffix="${mode_suffix}_depth4"; [[ "$RANKFORMULA_ABSTRACT_SRCPACK10" == 1 ]] && mode_suffix="${mode_suffix}_srcpack10"; [[ "$RANKFORMULA_GATHER_MLP" == 1 ]] && mode_suffix="${mode_suffix}_gathermlp"; (( MAXRREGCOUNT )) && mode_suffix="${mode_suffix}_r${MAXRREGCOUNT}"
OUT="$(build_path "${OUT:-oneesan_cuda_gridfp_b300_rankformula_nometa4_abstract_b${RANKFORMULA_NOMETA_BLOCK}${mode_suffix}_${TRANSPOSE_MODE}_n${N}}")"
NVCC_EXTRA=(); [[ "$PTXAS_VERBOSE" == 1 ]] && NVCC_EXTRA+=("-Xptxas=-v"); (( MAXRREGCOUNT )) && NVCC_EXTRA+=("-maxrregcount=$MAXRREGCOUNT")
TMPDIR="$ONEESAN_TMP_DIR" nvcc -O3 -std=c++17 -lineinfo -arch="$ARCH" \
  "${NVCC_EXTRA[@]}" -DTARGET_W="$W" -DLOW_LUT_K="$LOW_LUT_K" -DHIGH_LUT_K="$HIGH_LUT_K" \
  -DGPU_DIRECT_PM_ACCUM="$PM_ACCUM" -DBKCZ_TERNARY_KEY4="$TERNARY_KEY4" \
  -DP10DC_DECODE_LDG="$P10DC_DECODE_LDG" -DP10DC_RANKSTREAM_LUT_LDG="$P10DC_RANKSTREAM_LUT_LDG" \
  -DP10DC_RANKSTREAM_LUT_PAD256="$P10DC_RANKSTREAM_LUT_PAD256" \
  -DP10DC_RANKFORMULA_NOMETA_BLOCK="$RANKFORMULA_NOMETA_BLOCK" \
  -DP10DC_RANKFORMULA_NOMETA_WARPSHARE="$RANKFORMULA_NOMETA_WARPSHARE" \
  -DP10DC_RANKFORMULA_NOMETA_COOPGROUP="$RANKFORMULA_NOMETA_COOPGROUP" \
  -DP10DC_RANKFORMULA_NOMETA_COOP_UNROLL="$RANKFORMULA_NOMETA_COOP_UNROLL" \
  -DP10DC_RANKFORMULA_NOMETA_GROUP56="$RANKFORMULA_NOMETA_GROUP56" \
  -DP10DC_RANKFORMULA_NOMETA_GROUP61="$RANKFORMULA_NOMETA_GROUP61" \
  -DP10DC_RANKFORMULA_NOMETA_DIRECTMAP="$RANKFORMULA_NOMETA_DIRECTMAP" \
  -DP10DC_RANKFORMULA_DIRECTGATHER="$RANKFORMULA_DIRECTGATHER" \
  -DP10DC_RANKFORMULA_DIRECTGATHER_FORCE7="$RANKFORMULA_DIRECTGATHER_FORCE7" \
  -DP10DC_RANKFORMULA_MLP_WINDOW4="$RANKFORMULA_MLP_WINDOW4" \
  -DP10DC_RANKFORMULA_ABSTRACT_SELECT8="$RANKFORMULA_ABSTRACT_SELECT8" \
  -DP10DC_RANKFORMULA_ABSTRACT_DEPTH4="$RANKFORMULA_ABSTRACT_DEPTH4" \
  -DP10DC_RANKFORMULA_ABSTRACT_SRCPACK10="$RANKFORMULA_ABSTRACT_SRCPACK10" \
  -DP10DC_RANKFORMULA_GATHER_MLP="$RANKFORMULA_GATHER_MLP" \
  -DP10DC_RANKCHUNK32_ONESHFL=1 -DP10DC_RANKCHUNK32_FUSED16=0 -DP10DC_RANKCHUNK32_BYTEPACK=0 \
  -DP10DC_RANKCHUNK32_ALIGN32=0 -DP10DC_RANKCHUNK32_BLOCK64=0 -DP10DC_RANKDELTA8_FUSED13=1 \
  -DP10DC_RANKFORMULA_SPARSE_BASE=1 -DP10DC_RANKFORMULA_RAWCODE=1 -DP10DC_RANKFORMULA_INLINE_CROSS=1 \
  -DP10DC_RANKFORMULA_BASE_DELTA=0 -DP10DC_RANKFORMULA_SLOTMETA=0 -DP10DC_RANKFORMULA_SLOTROW32=0 \
  "$SRC" -o "$OUT"
ABSTRACT_LUT_BYTES=94206
if [[ "$RANKFORMULA_ABSTRACT_SELECT8" == 1 ]]; then ABSTRACT_LUT_BYTES=171866; fi
if [[ "$RANKFORMULA_ABSTRACT_DEPTH4" == 1 ]]; then ABSTRACT_LUT_BYTES=108326; fi
if [[ "$RANKFORMULA_ABSTRACT_SRCPACK10" == 1 ]]; then ABSTRACT_LUT_BYTES=149598; fi
if [[ "$RANKFORMULA_ABSTRACT_DEPTH4" == 1 && "$RANKFORMULA_ABSTRACT_SRCPACK10" == 1 ]]; then ABSTRACT_LUT_BYTES=86058; fi
ABSTRACT_OFF_DEVICE_BYTES=480
if [[ "$RANKFORMULA_NOMETA_GROUP56" == 1 ]]; then ABSTRACT_LUT_BYTES=$((ABSTRACT_LUT_BYTES - 480)); ABSTRACT_OFF_DEVICE_BYTES=0; fi
echo "built $OUT (closure=pattern10-depthcode high_ctx=rankformula-nometa-abstract block=$RANKFORMULA_NOMETA_BLOCK warpshare=$RANKFORMULA_NOMETA_WARPSHARE coopgroup=$RANKFORMULA_NOMETA_COOPGROUP coop_unroll=$RANKFORMULA_NOMETA_COOP_UNROLL group56=$RANKFORMULA_NOMETA_GROUP56 group61=$RANKFORMULA_NOMETA_GROUP61 directmap=$RANKFORMULA_NOMETA_DIRECTMAP directgather=$RANKFORMULA_DIRECTGATHER directgather_force7=$RANKFORMULA_DIRECTGATHER_FORCE7 mlp_window4=$RANKFORMULA_MLP_WINDOW4 select8=$RANKFORMULA_ABSTRACT_SELECT8 depth4=$RANKFORMULA_ABSTRACT_DEPTH4 srcpack10=$RANKFORMULA_ABSTRACT_SRCPACK10 gather_mlp=$RANKFORMULA_GATHER_MLP maxrregcount=$MAXRREGCOUNT pm_accum=$PM_ACCUM per_code_metadata_bytes=0 abstract_lut_bytes=$ABSTRACT_LUT_BYTES abstract_off_device_bytes=$ABSTRACT_OFF_DEVICE_BYTES ballot_runtime_loads=0 transpose=$TRANSPOSE_MODE ptxas_verbose=$PTXAS_VERBOSE)"
